<?php require 'includes/bootstrap.php'; $title='Phòng & suite'; $in=input('check_in',date('Y-m-d')); $out=input('check_out',date('Y-m-d',strtotime('+1 day'))); $error=''; $quantity=1;$guests=2;
try { $nights=valid_dates($in,$out); $quantity=integer('quantity',1,5); $guests=integer('guests',1,20,2); } catch(DomainException $ex) {$error=$ex->getMessage();}
$rooms=query('SELECT * FROM room_types WHERE active=1 ORDER BY price')->fetchAll(); require 'includes/header.php'; ?>
<section class="page-heading"><div class="eyebrow">YOUR PRIVATE RETREAT</div><h1>Chọn một <em>chốn riêng.</em></h1><p>Ba sắc thái nghỉ dưỡng. Một tinh thần hiếu khách.</p></section><div class="section compact"><?php require 'includes/search.php'; ?>
<?php if($error): ?><div class="notice error" role="alert"><?=e($error)?></div><?php else: ?><p class="result-count"><?=$nights?> đêm · <?=$quantity?> phòng · <?=$guests?> khách · Giá đã gồm thuế và bữa sáng</p><div class="room-list"><?php $matches=0; foreach($rooms as $room): $left=available($room,$in,$out); $fits=$guests<=$quantity*$room['capacity']; $ok=$left>=$quantity && $fits; if($ok) $matches++; ?><article class="room-row"><img src="<?=e(url('assets/images/'.$room['image']))?>" alt="<?=e($room['name'])?>"><div class="room-info"><div class="eyebrow"><?=e($room['subtitle'])?></div><h2><?=e($room['name'])?></h2><p><?=e($room['area'])?> m² · Tối đa <?=e($room['capacity'])?> khách/phòng</p><p><?=e($room['description'])?></p><a class="text-link" href="<?=e(url('room.php?id='.$room['id']))?>">Chi tiết & tiện nghi ↗</a></div><div class="room-price"><span class="badge <?=$ok?'':'muted'?>"><?=$ok?'Còn '.$left.' phòng':($fits?'Không đủ phòng':'Vượt sức chứa')?></span><h3><?=money($room['price'])?></h3><small>mỗi phòng / đêm</small><p>Tổng <?=$nights?> đêm<br><strong><?=money($room['price']*$quantity*$nights)?></strong></p><?php if($ok): ?><a class="button" href="<?=e(url('booking.php?'.http_build_query(['id'=>$room['id'],'check_in'=>$in,'check_out'=>$out,'quantity'=>$quantity,'guests'=>$guests])))?>">CHỌN PHÒNG ↗</a><?php else: ?><p class="muted-text">Hãy đổi ngày, số phòng hoặc số khách.</p><?php endif; ?></div></article><?php endforeach; ?></div><?php if(!$matches): ?><div class="notice">Không có lựa chọn phù hợp. Vui lòng thay đổi ngày hoặc số lượng khách/phòng.</div><?php endif; endif; ?></div><?php require 'includes/footer.php'; ?>
